import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const base='/Volumes/alex/CodexMigrationStaging';
const name='practice-main36-local-qualification-20261019-evidence';
const archive=base+'/practice-main36-qualified-packet-gys7tV/'+name+'.tgz';
const hash=b=>createHash('sha256').update(b).digest('hex');
const free=await fs.statfs('/private/tmp');assert(free.bavail*free.bsize>=2*1024**3);
const owned=await fs.mkdtemp('/private/tmp/practice-main36-packet-audit-');
const b=await fs.readFile(archive);assert.equal(b.length,19121762);
const local=owned+'/'+name+'.tgz';await fs.writeFile(local,b,{flag:'wx'});
const started=Date.now();execFileSync('/usr/bin/tar',['-xzf',local,'-C',owned],{timeout:120000});
const inventory=JSON.parse(await fs.readFile(owned+'/'+name+'/inventory.json'));
const original=JSON.parse(await fs.readFile(base+'/practice-main36-qualified-packet-gys7tV/'+name+'/inventory.json'));
assert.deepEqual(inventory,original);assert.equal(inventory.files.length,221);
for(const f of inventory.files){assert(!f.path.startsWith('/')&&!f.path.split('/').includes('..'));const v=await fs.readFile(owned+'/'+name+'/'+f.path);assert.equal(v.length,f.bytes);assert.equal(hash(v),f.sha256);}
assert.equal(hash(await fs.readFile(archive)),hash(b));
const r={format:'PracticeEvidenceArchiveAudit.v1',passed:true,archive,bytes:b.length,sha256:hash(b),files:inventory.files.length,expandedBytes:inventory.files.reduce((n,r)=>n+r.bytes,0),extractedAndRehashed:true,localExtractionMs:Date.now()-started,localAuditDirectory:owned,initialShareExtraction:{passed:false,deadlineMs:120000,error:'spawnSync /usr/bin/tar ETIMEDOUT',signal:'SIGTERM',partialOutput:base+'/practice-main36-qualified-audit-I5HwGh',sourceScript:'/private/tmp/practice-main36-retain-20261019.mjs'},scope:'Same immutable archive independently extracted locally and all 221 inventoried files rehashed. The initial share extraction timed out and remains retained. No test result, deadline, source or package was altered.'};
await fs.writeFile(base+'/practice-main36-local-qualification-packet-20261019.json',JSON.stringify(r,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(r));
